import type { File } from '../../../../shared/contracts/files';
/**
 * The picker's selection is the value the field will hold once confirmed:
 * whole `File` objects, in order. Assets already in the field come first, new
 * picks are appended in the order they are clicked.
 */
export type PickerSelection = File[];
export declare const hasFile: (selection: PickerSelection, id: number) => boolean;
/**
 * Adds the file, or removes it if it is already there. On a single-value field
 * a new pick replaces whatever was selected.
 */
export declare const toggleFile: (selection: PickerSelection, file: File, { multiple }: {
    multiple: boolean;
}) => PickerSelection;
/** Appends every file not already selected, keeping their order (select-all). */
export declare const addFiles: (selection: PickerSelection, files: File[]) => PickerSelection;
export declare const removeFile: (selection: PickerSelection, id: number) => PickerSelection;
export declare const removeFiles: (selection: PickerSelection, ids: Set<number>) => PickerSelection;
/**
 * Moves one file to where another one is, the others shifting to make room.
 * Unknown ids leave the selection as it is.
 */
export declare const moveFile: (selection: PickerSelection, activeId: number, overId: number) => PickerSelection;
/** Same files in the same order: confirming would change nothing. */
export declare const isSameSelection: (a: PickerSelection, b: PickerSelection) => boolean;
